#!/usr/bin/env python3
import argparse,hashlib,json,math,os
from pathlib import Path
import numpy as np
def sh(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def atom(p,v):p=Path(p);t=p.with_suffix(p.suffix+'.tmp');t.write_text(json.dumps(v,indent=2,sort_keys=True)+'\n');os.replace(t,p)
def order(c,f,cn,fn):return None if c<=0 or f<=0 or c==f else math.log(c/f)/math.log((fn-1)/(cn-1))
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,required=True);ap.add_argument('--namespace',type=Path,required=True);a=ap.parse_args();root=a.root.resolve();ns=a.namespace.resolve();out=ns/'output';rp=out/'RESULT.json';tp=out/'TERMINAL.json';ep=out/'EVIDENCE.npz';r=json.loads(rp.read_text());t=json.loads(tp.read_text());f=json.loads((ns/'FREEZE_RECORD.json').read_text());b=json.loads((ns/'BINDINGS.json').read_text());c={'terminal':r['status']==t['status']=='COMPLETE','classification':r['classification']==t['classification'],'result_hash':sh(rp)==t['result_sha256'],'evidence_hash':sh(ep)==t['evidence_sha256'],'contract':r['contract_sha256']==sh(ns/'CONTRACT.md'),'bindings':r['bindings_sha256']==sh(ns/'BINDINGS.json')};fm={x['path']:sh(ns/x['path'])==x['sha256'] for x in f['files']};pm={x['path']:sh(root/x['path'])==x['sha256'] for x in b['parents']+b['production_sources']};c['frozen']=all(fm.values());c['parents']=all(pm.values());A=r['producer_A'];B=r['producer_B'];c['A_zero']=A['background_maximum_normalized']==0.;c['A_response']=A['perturbation_control']['finite'] and A['perturbation_control']['maximum_normalized']>1e-12;c['A_decision']=all(A['gates'].values())==A['passed'];lv=B['levels'];c['B_grids']=[x['grid'] for x in lv]==[[65,241],[97,241],[129,241],[193,241],[257,241]];pas=[i for i,x in enumerate(lv) if x['finite'] and x['maximum_normalized']<=1e-4];last=order(lv[-2]['maximum_normalized'],lv[-1]['maximum_normalized'],lv[-2]['grid'][0],lv[-1]['grid'][0]);ex={'finest':lv[-1]['maximum_normalized']<=1e-4,'monotone':all(y['maximum_normalized']<x['maximum_normalized'] for x,y in zip(lv[:-1],lv[1:])),'last_order':last is not None and 2<=last<=6,'two_consecutive':len(pas)>=2 and pas[-2:]==[len(lv)-2,len(lv)-1]};c['B_decision']=ex==B['gates'] and pas==B['passing_indices'] and all(ex.values())==B['passed'];
 with np.load(ep,allow_pickle=False) as e:c['finite_evidence']=all(np.all(np.isfinite(e[n])) for n in e.files)
 ok=all(c.values());audit={'schema':'lin-d1-gh-independent-audit-v1','classification':'VERIFIED' if ok else 'NOT_VERIFIED','producer_classification':r['classification'],'checks':c,'freeze_matches':fm,'parent_matches':pm,'B_expected_gates':ex,'claim_boundary':'immediate finite-resolution equilibrium preservation only'};atom(out/'INDEPENDENT_AUDIT.json',audit);print(json.dumps(audit,indent=2,sort_keys=True));raise SystemExit(0 if ok else 1)
if __name__=='__main__':main()
